import{_ as t,C as l,c as a,o as i,a3 as o,G as s}from"./chunks/framework.Dokpd4od.js";const k=JSON.parse('{"title":"Skills report","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/reporting/skills-report.md","filePath":"master/human-resources/employees/reporting/skills-report.md","lastUpdated":1792041590000}'),n={name:"master/human-resources/employees/reporting/skills-report.md"};function p(h,e,d,c,g,m){const r=l("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=o('<h1 id="skills-report" tabindex="-1">Skills report <a class="header-anchor" href="#skills-report" aria-label="Permalink to &quot;Skills report&quot;">​</a></h1><p>The Skills report shows which employee has which skill, and at what level. Use it to find people for a job, spot gaps in a team or check that skills are recorded. The report only reads data. You add or change skills on each employee.</p><blockquote><p><strong>In simple words:</strong> It is one big table of every skill of every person.</p></blockquote><p>Open <code>Employees → Reportings</code>. The report opens as <strong>Skills</strong>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>Skills come from the <strong>Manage Skills</strong> page of each employee. See <a href="./../employees/skills-and-resume.html">Skills and resume</a>. Skill types are set up in <a href="./../setup/skill-types.html">Skill types</a>.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>There is no create button and no row action. You can only read, search, filter and group.</p>',7)),s(r,{src:"/images1/employees/rep_skills_default.png",alt:"Skills report with columns Employee, Skill, Level, Proficiency and Skill Type"}),e[1]||(e[1]=o('<h3 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h3><p>The report lists skill records, not employees.</p><ul><li><strong>Default:</strong> every skill record. The report has four tabs in all.</li><li><strong>With Skill:</strong> the same list of records as <strong>Default</strong>.</li><li><strong>Without Skill:</strong> empty, with the message <strong>No Skills</strong>.</li><li><strong>Archived:</strong> empty unless you have archived records.</li></ul><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong>Employee:</strong> the person.</li><li><strong>Skill:</strong> the skill, such as Communication.</li><li><strong>Level:</strong> the grade, such as Intermediate, shown as a badge.</li><li><strong>Proficiency:</strong> the level as a percentage bar.</li><li><strong>Skill Type:</strong> the group of the skill, shown as a badge.</li></ul><h3 id="search-group-and-filter" tabindex="-1">Search, group and filter <a class="header-anchor" href="#search-group-and-filter" aria-label="Permalink to &quot;Search, group and filter&quot;">​</a></h3><p>Use the search box to narrow the rows. A column-toggle icon shows or hides columns. Group by has a direction select: <strong>Ascending</strong> or <strong>Descending</strong>. You can group by <strong>Employee</strong> or <strong>Skill Type</strong>. Groups start expanded. Open the filter to use <strong>Employee</strong>, <strong>Skill</strong>, <strong>Level</strong> or <strong>Skill Type</strong>.</p>',7)),s(r,{src:"/images1/employees/rep_skills_filter.png",alt:"Filter panel of the Skills report with Employee, Skill, Level and Skill Type"}),e[2]||(e[2]=o('<h2 id="read-the-report" tabindex="-1">Read the report <a class="header-anchor" href="#read-the-report" aria-label="Permalink to &quot;Read the report&quot;">​</a></h2><p>Look at Priya Sharma in the report. She has one row once you add her skill in the tutorial: Skill <strong>Communication</strong>, Level <strong>Intermediate</strong>, Proficiency 50.00%, Skill Type <strong>Soft Skills</strong>.</p><ol><li>Open <code>Employees → Reportings</code>.</li><li>Group by <strong>Employee</strong>, or type <code>Priya</code> in the search box. The list narrows to her group.</li><li>Read the row. It matches what is on her <strong>Manage Skills</strong> page.</li></ol>',3)),s(r,{src:"/images1/employees/rep_skills_priya.png",alt:"Skills report searched for Priya, showing her group with Communication, Intermediate, 50.00% and Soft Skills"}),e[3]||(e[3]=o('<p>To find everyone with a skill, open the filter, pick the <strong>Skill</strong>, then read the <strong>Employee</strong> column. Group by <strong>Skill Type</strong> to compare teams side by side.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use <strong>With Skill</strong> or <strong>Default</strong> to read every skill record. Both show the same rows.</p></div><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>The report is not stored separately. It reads the skills on each employee. When you add or change a skill there, the report shows it at once.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../employees/skills-and-resume.html">Skills and resume</a></li><li><a href="./../setup/skill-types.html">Skill types</a></li><li><a href="./../employees/employee-list.html">Employee list</a></li></ul>',6))])}const y=t(n,[["render",p]]);export{k as __pageData,y as default};
